def apply(inp):
    g=[r[:] for r in inp]
    seen=[[False]*10 for _ in range(10)]
    for r in range(10):
        for c in range(10):
            if inp[r][c]==5 and not seen[r][c]:
                st=[(r,c)]; seen[r][c]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<10 and 0<=y<10 and inp[x][y]==5 and not seen[x][y]:
                            seen[x][y]=True; st.append((x,y))
                rows=[p[0] for p in cells]; cols=[p[1] for p in cells]
                top,bot,l,rgt=min(rows),max(rows),min(cols),max(cols)
                gap=[c for c in range(l,rgt+1) if inp[top][c]==0][0]
                if gap-l==2:   # orientation A
                    bar=range(0,gap+1); block=(gap-1,gap)
                else:          # orientation B
                    bar=range(gap,10); block=(gap,gap+1)
                for cc in bar: g[top-1][cc]=2
                for rr in range(top,bot):
                    for cc in block:
                        if g[rr][cc]!=5: g[rr][cc]=2
    return g

